@test
def test_cubic_classes():
    cs = I.CubicSpline(xi, yi, bc_type="natural")
    assert isinstance(cs, I.PPoly)
    assert closec(cs(q), [0.19863230267060256, 0.9911294327067088, 0.23690313586550724, 0.8414709848078965, -0.2954977085670033], 1e-09)
    assert closec(cs.c, [-0.16338302926003223, -0.12212559290392022, -0.05724541518049975, 0.04261530843760917, 0.19612110274591135, 2.220446049250313e-16, -0.24507454389004613, -0.428262933245926, -0.5141310560166757, -0.4118543157664136, 0.999696834523414, 0.8771595625783901, 0.5404908240104038, 0.06929382937910294, -0.6714944680473683, 0.0, 0.479425538604203, 0.8414709848078965, 0.9974949866040544, 0.7457052121767204], 1e-09)
    assert closec(cs.derivative()(q), [0.9800908710122102, -0.1312447560150542, -0.9539088560014805, 0.5404908240104038, 0.9555834166232051], 1e-09)
    assert closec([cs.integrate(0.0, 2.0)], [1.4158583631322945], 1e-09)
    assert closec(I.PchipInterpolator(xi, yi)(q), [0.20664176941351828, 0.9756345531215614, 0.25117818726998137, 0.8414709848078965, -0.33928211021211074], 1e-09)
    assert closec(I.Akima1DInterpolator(xi, yi, method='makima')(q), [0.2052999825987558, 0.9789357990360308, 0.24599179743033225, 0.8414709848078965, NAN], 1e-09)
    assert closec(I.CubicHermiteSpline(xi, yi, np.cos(xi))(q), [0.19863382661794157, 0.9910961203353934, 0.23918581127612443, 0.8414709848078965, -0.29585236345487237], 1e-09)
test_cubic_classes()
